CREATE TABLE IF NOT EXISTS institutions(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,university VARCHAR(180) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS academic_years(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,name VARCHAR(60) NOT NULL,UNIQUE(institution_id,name),FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS departments(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,name VARCHAR(180) NOT NULL,UNIQUE(institution_id,name),FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stages(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,department_id INT NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE(department_id,name),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subjects(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,department_id INT NOT NULL,stage_id INT NOT NULL,name VARCHAR(180) NOT NULL,UNIQUE(stage_id,name),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(stage_id) REFERENCES stages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,year_id INT NOT NULL,department_id INT NOT NULL,stage_id INT NOT NULL,code VARCHAR(60) NOT NULL,name VARCHAR(180) NOT NULL,shift VARCHAR(20) NOT NULL,section_name VARCHAR(80) NOT NULL DEFAULT '',needs_access TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,portal_hash CHAR(64) NULL UNIQUE,UNIQUE(institution_id,year_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(year_id) REFERENCES academic_years(id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(stage_id) REFERENCES stages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rooms(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,building VARCHAR(120) NOT NULL,floor_name VARCHAR(40) NOT NULL,rows_count INT NOT NULL,cols_count INT NOT NULL,capacity INT NOT NULL,status VARCHAR(20) NOT NULL,board VARCHAR(20) NOT NULL DEFAULT 'north',entrance VARCHAR(100) NOT NULL DEFAULT '',required_monitors INT NOT NULL DEFAULT 2,UNIQUE(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_seats(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,room_id INT NOT NULL,row_no INT NOT NULL,col_no INT NOT NULL,label VARCHAR(40) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'active',`accessible` TINYINT NOT NULL DEFAULT 0,UNIQUE(room_id,row_no,col_no),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exam_periods(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,year_id INT NOT NULL,name VARCHAR(180) NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,exam_round VARCHAR(40) NOT NULL DEFAULT 'الأول',term_name VARCHAR(60) NOT NULL DEFAULT '',study_system VARCHAR(40) NOT NULL DEFAULT 'فصلي',adjacency VARCHAR(20) NOT NULL DEFAULT 'horizontal',`grouping` VARCHAR(20) NOT NULL DEFAULT 'subject',strict_separation TINYINT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'draft',approved_snapshot LONGTEXT NULL,revision INT NOT NULL DEFAULT 0,FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(year_id) REFERENCES academic_years(id),INDEX(institution_id,starts_at,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS period_rooms(institution_id INT NOT NULL,period_id INT NOT NULL,room_id INT NOT NULL,PRIMARY KEY(period_id,room_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(period_id) REFERENCES exam_periods(id),FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exam_candidates(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,period_id INT NOT NULL,student_id INT NOT NULL,subject_id INT NOT NULL,carry_note TEXT NOT NULL,UNIQUE(period_id,student_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(period_id) REFERENCES exam_periods(id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS seating_assignments(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,period_id INT NOT NULL,student_id INT NOT NULL,seat_id INT NOT NULL,UNIQUE(period_id,student_id),UNIQUE(period_id,seat_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(period_id) REFERENCES exam_periods(id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(seat_id) REFERENCES room_seats(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invigilators(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,name VARCHAR(180) NOT NULL,academic_title VARCHAR(100) NOT NULL,department_id INT NULL,duty VARCHAR(20) NOT NULL DEFAULT 'any',baseline_minutes INT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,portal_hash CHAR(64) NULL UNIQUE,FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invigilator_availability(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,invigilator_id INT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason VARCHAR(180) NOT NULL,FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(invigilator_id) REFERENCES invigilators(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invigilation_assignments(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,period_id INT NOT NULL,room_id INT NOT NULL,invigilator_id INT NOT NULL,role VARCHAR(20) NOT NULL,UNIQUE(period_id,invigilator_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(period_id) REFERENCES exam_periods(id),FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(invigilator_id) REFERENCES invigilators(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS map_versions(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,period_id INT NOT NULL,revision INT NOT NULL,action VARCHAR(100) NOT NULL,snapshot LONGTEXT NOT NULL,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(period_id,revision),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(period_id) REFERENCES exam_periods(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,user_id INT NOT NULL,action VARCHAR(120) NOT NULL,details TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
